    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # A one-cell hole enclosed by a horizontal bar marks a vertical ray.
    markers = {}
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            color = row[c - 1]
            if color != 0 and row[c] == 0 and row[c + 1] == color:
                markers.setdefault(c, []).append((r, color))
    for c, points in markers.items():
        # Original vertical pixels are anchors too; their color fills up to
        # the nearest horizontal marker beneath them.
        anchors = [(r, color, True) for r, color in points]
        anchors.extend((r, grid[r][c], False) for r in range(h) if grid[r][c] != 0)
        anchors.sort(key=lambda item: item[0])
        if not anchors:
            continue
        # Above the first marker, project its color to the top edge.
        first_r, first_color, first_is_marker = anchors[0]
        for y in range(first_r):
            if out[y][c] == 0:
                out[y][c] = first_color
        # Each interval takes the color of its lower anchor (a later hole or
        # the existing vertical object below).
        for (r1, color1, _), (r2, color2, _) in zip(anchors, anchors[1:]):
            for y in range(r1 + 1, r2):
                if out[y][c] == 0:
                    out[y][c] = color2
        # Fill each marked hole itself with its bar color.
        for r, color in points:
            out[r][c] = color
    return out
